+function makeKart(color='#ef6d4d',isPlayer=false){const root=new THREE.Group();const body=new THREE.Mesh(new THREE.BoxGeometry(1.75,.58,2.25),mat(color,.48));body.position.y=.75;body.castShadow=true;root.add(body);const nose=new THREE.Mesh(new THREE.BoxGeometry(1.48,.27,.62),mat(isPlayer?'#ffe06b':'#fff1b5',.42));nose.position.set(0,.95,-.84);nose.castShadow=true;root.add(nose);const seat=new THREE.Mesh(new THREE.BoxGeometry(1,.58,.85),mat('#304b55'));seat.position.set(0,1.18,.38);seat.castShadow=true;root.add(seat);const head=new THREE.Mesh(new THREE.SphereGeometry(.43,16,12),mat(isPlayer?'#86dc91':'#f5bc84'));head.position.set(0,1.7,.32);head.castShadow=true;root.add(head);const cap=new THREE.Mesh(new THREE.SphereGeometry(.46,16,10),mat(isPlayer?'#3ac584':color));cap.scale.y=.54;cap.position.set(0,2,.32);cap.castShadow=true;root.add(cap);for(const x of [-.19,.19]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.055,8,8),mat('#243b45'));eye.position.set(x,1.73,-.08);root.add(eye)}for(const x of [-1,1])for(const z of [-.72,.78]){const w=new THREE.Mesh(new THREE.CylinderGeometry(.32,.32,.23,12),dark);w.rotation.z=Math.PI/2;w.position.set(x*.91,.46,z);w.castShadow=true;root.add(w);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.11,.11,.245,10),gold);hub.rotation.z=Math.PI/2;hub.position.copy(w.position);root.add(hub)}const spoiler=new THREE.Mesh(new THREE.BoxGeometry(1.25,.13,.35),mat('#fce5a0'));spoiler.position.set(0,1.25,1);root.add(spoiler);scene.add(root);return root}
