+let started=false,finished=false,paused=false,playerT=0,playerLane=0,speed=0,lap=1,raceTime=0,held={},item=null,boost=0,drift=0,toastTimeout,prev=performance.now(),sound=true,lapToast=false;
+const $=s=>document.querySelector(s);const ord=['ST','ND','RD','TH'];function notify(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),1600)}
+function reset(){started=false;finished=false;playerT=0;playerLane=0;speed=0;lap=1;raceTime=0;item=null;boost=0;drift=0;lapToast=false;bots.forEach((_,i)=>bots[i].userData.t=-.012*(i+1));pickups.forEach(p=>{p.taken=false;p.mesh.visible=true});$('#startScreen').classList.remove('hidden');$('#finishScreen').classList.add('hidden');$('#raceHud').classList.add('paused-ui');$('#speed').textContent='0';$('#speedFill').style.width='0%';$('#lap').textContent='1';$('#lapFill').style.width='0%';$('#itemIcon').textContent='?';$('#itemSlot').classList.remove('ready');$('#controlsHint').classList.remove('paused-ui')}
+function begin(){if(started)return;$('#startScreen').classList.add('hidden');$('#raceHud').classList.remove('paused-ui');const cd=$('#countdown');let n=3;cd.classList.add('show');cd.firstElementChild.textContent=n;const tick=()=>{if(n===0){cd.classList.remove('show');started=true;return}cd.firstElementChild.textContent=n--;cd.firstElementChild.style.animation='none';void cd.firstElementChild.offsetWidth;cd.firstElementChild.style.animation='';setTimeout(tick,760)};tick()}
+$('#startBtn').onclick=begin;$('#againBtn').onclick=reset;$('#touchItem').onclick=useItem;$('#soundBtn').onclick=()=>{$('#soundBtn').classList.toggle('muted');sound=!sound;$('#soundBtn').innerHTML=sound?'♫ <span>SOUND ON</span>':'♫ <span>SOUND OFF</span>'};
+window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();held[e.key.toLowerCase()]=true;if(e.code==='Space'||e.key.toLowerCase()==='x')useItem();if(e.key==='Enter'&&!started&&!finished)begin()});window.addEventListener('keyup',e=>held[e.key.toLowerCase()]=false);document.querySelectorAll('.touch-controls [data-key]').forEach(b=>{const k=b.dataset.key.toLowerCase();b.addEventListener('pointerdown',e=>{e.preventDefault();held[k]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>held[k]=false))});
+function useItem(){if(!started||!item||finished)return;const used=item;item=null;$('#itemSlot').classList.remove('ready');$('#itemIcon').textContent='?';if(used==='⚡'){boost=2.5;notify('TURBO BOOST!');burst(player.position,'#ffe356')}else if(used==='🍌'){notify('BANANA DROP!');const p=point(playerT,-playerLane);const b=new THREE.Mesh(new THREE.TorusGeometry(.25,.12,8,12),gold);b.rotation.x=Math.PI/2;b.position.set(p.x,.15,p.z);scene.add(b);setTimeout(()=>scene.remove(b),7000)}else{boost=1.2;notify('SHELL SHIELD!');burst(player.position,'#68e7c0')}}
+function setKartPose(k,t,lane,dt,steer=0){const p=point(t,lane);k.position.set(p.x,.02,p.z);const tangent=point(t+.005,lane).sub(point(t-.005,lane));k.rotation.y=-Math.atan2(tangent.z,tangent.x)+Math.PI/2;k.rotation.y+=steer*.13;k.rotation.z=THREE.MathUtils.lerp(k.rotation.z,-steer*.09,.08);}
+const cameraLook=new THREE.Vector3();function frame(now){requestAnimationFrame(frame);const dt=Math.min(.04,(now-prev)/1000);prev=now;
+for(const p of pickups)if(!p.taken){p.mesh.rotation.y+=dt*.85;p.mesh.position.y=1.08+Math.sin(now*.002+p.phase)*.14}
+if(started&&!finished&&!paused){raceTime+=dt;const accelerate=held.w||held.arrowup,brake=held.s||held.arrowdown,left=held.a||held.arrowleft,right=held.d||held.arrowright;const steer=(right?1:0)-(left?1:0);speed+=((accelerate?19:0)-(brake?27:0)-(accelerate?0:7))*dt;if(boost>0){boost-=dt;speed+=35*dt}speed=THREE.MathUtils.clamp(speed,0,68);const grip=THREE.MathUtils.lerp(1,.58,Math.min(1,Math.abs(steer)*speed/40));playerT+=(speed/Math.max(rx,rz)*.00095*dt*60);playerLane=THREE.MathUtils.clamp(playerLane+steer*dt*(1.7+speed*.045),-3.3,3.3);if(Math.abs(playerLane)>2.9)speed=Math.max(8,speed-22*dt);if(brake&&steer&&speed>15){drift+=dt;if(drift>.7&&Math.random()<dt*1.1)boost=Math.max(boost,.6)}else drift=0;setKartPose(player,playerT,playerLane,dt,steer*grip);
+for(let i=0;i<bots.length;i++){const b=bots[i],v=[.00104,.00098,.00108][i];b.userData.t=(b.userData.t||0)+v*dt*60;setKartPose(b,b.userData.t,[-1.5,1.35,-.35][i],dt,Math.sin(now*.001+i)*.3)}
+for(const p of pickups){if(p.taken)continue;let d=Math.abs(((playerT-p.t+Math.PI*3)%(Math.PI*2))-Math.PI);if(d<.09&&Math.abs(playerLane)<4.5){p.taken=true;p.mesh.visible=false;item=['⚡','🍌','🐚'][Math.floor(Math.random()*3)];$('#itemIcon').textContent=item;$('#itemSlot').classList.add('ready');notify('POWER-UP! PRESS SPACE');}}
+if(playerT>=Math.PI*2){playerT-=Math.PI*2;lap++;$('#lap').textContent=Math.min(lap,3);if(lap>3){finished=true;const rank=getRank();$('#finishTitle').textContent=rank===1?'YOU WIN!':'RACE COMPLETE!';$('#finishText').textContent=`You finished ${rank}${ord[rank-1]} in ${formatTime(raceTime)}. ${rank===1?'The Meadow Cup is yours!':'The podium is waiting — give it another go!'}`;$('#finishScreen').classList.remove('hidden')}else{notify(`LAP ${lap-1} COMPLETE!`);lapToast=true}}
+const prog=(playerT%(Math.PI*2))/(Math.PI*2);$('#lapFill').style.width=`${Math.min(100,Math.max(0,prog*100))}%`;$('#timer').textContent=formatTime(raceTime);$('#speed').textContent=Math.round(speed*3.5);$('#speedFill').style.width=`${speed/68*100}%`;$('#position').textContent=getRank();$('#ordinal').textContent=ord[getRank()-1]||'TH';}
+const tangent=point(playerT+.02,playerLane).sub(point(playerT-.02,playerLane)).normalize();const target=player.position.clone().add(new THREE.Vector3(0,1.2,0));const desired=player.position.clone().add(new THREE.Vector3(0,5.1,0)).addScaledVector(tangent,-10.7);camera.position.lerp(desired,1-Math.pow(.001,dt));cameraLook.lerp(target,1-Math.pow(.001,dt));camera.lookAt(cameraLook);camera.fov=THREE.MathUtils.lerp(camera.fov,57+speed*.12,.04);camera.updateProjectionMatrix();for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.v.y-=8*dt;p.mesh.position.addScaledVector(p.v,dt);p.mesh.scale.setScalar(Math.max(.01,p.life));if(p.life<=0){scene.remove(p.mesh);particles.splice(i,1)}}renderer.render(scene,camera)}
+function getRank(){let rank=1;for(const b of bots){let bt=(b.userData.t||0)+Math.PI*2*(lap-1);let pt=playerT+Math.PI*2*(lap-1);if(bt>pt)rank++}return rank}
+function formatTime(t){const m=Math.floor(t/60),s=Math.floor(t%60),d=Math.floor(t%1*10);return`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}.${d}`}
+window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))});reset();requestAnimationFrame(frame);
